INSERT INTO ops._bkp_history_uncap_20260929 SELECT 'equipment_oee_daily', id_equipment, ts_value::timestamptz, oee, oee_p FROM gold.equipment_oee_daily WHERE ts_value < '2026-08-31' AND ((oee_p = 1 AND running_time>0 AND ideal_production>0 AND gross*available_time > 1.0001*ideal_production*running_time) OR (oee = 1 AND ideal_production>0 AND net > 1.0001*ideal_production));
