UPDATE gold.site_oee_shift SET oee_p = CASE WHEN oee_p > 10 THEN NULL ELSE oee_p END, oee = CASE WHEN oee > 10 THEN NULL ELSE oee END WHERE ts_value < '2026-08-31' AND (oee_p > 10 OR oee > 10);
